end)()
HUD.font=(function()
-- Native text bounds; no rectangle glyph renderer.
local M={}
function M.supported(name)return HUD.native_font_data.faces[name or 'bigblue']~=nil end
function M.measure(text,size,name,continuous)
    local face=HUD.native_font_data.faces[name or 'bigblue']
    local sr=rawget(_G,'stingray')
    if sr and HUD.native_font then local f,m,active=HUD.native_font.resolve(sr,name,false);face=active end
    if not face then return 0,-size*.2,#text*size*.6,size*.8 end
    local factor=size/face.em;local left,bottom,right,top,offset=0,0,0,0,0
    local digits=text:match('^(%d%d%d%d*)')
    local fixed
    if digits then
        fixed={0,0,0,0,0}
        for digit=48,57 do local g=face.glyphs[digit] or face.glyphs[63];fixed[1]=math.max(fixed[1],g[1]);fixed[2]=math.min(fixed[2],g[2]);fixed[3]=math.min(fixed[3],g[3]);fixed[4]=math.max(fixed[4],g[4]);fixed[5]=math.max(fixed[5],g[5]) end
    end
    for i=1,#text do
        local g=face.glyphs[text:byte(i)] or face.glyphs[63]
        if fixed and i<=#digits then g=fixed end
        left=math.min(left,offset+g[2]);bottom=math.min(bottom,g[3])
        right=math.max(right,offset+g[4]);top=math.max(top,g[5]);offset=offset+g[1]
    end
    return left*factor,bottom*factor,right*factor,top*factor
end
function M.numeric_parts(command)
    local digits=command.numeric_display and command.text:match('^(%d%d%d%d*)')
    if not digits then return {{text=command.text,dx=0,alpha=1}} end
    local face=HUD.native_font_data.faces[command.font or 'bigblue']
    local sr=rawget(_G,'stingray')
    if sr then local f,m,active=HUD.native_font.resolve(sr,command.font,false);face=active end
    local advance=command.size*.6
    if face then
        advance=0
        for digit=48,57 do advance=math.max(advance,(face.glyphs[digit] or face.glyphs[63])[1]*command.size/face.em) end
    end
    local leading=digits:match('^(0*)') or '';local dim=math.min(#leading,#digits-1)
    local parts={}
    for i=1,#digits do parts[#parts+1]={text=digits:sub(i,i),dx=(i-1)*advance,alpha=i<=dim and 1/3 or 1} end
    if #command.text>#digits then parts[#parts+1]={text=command.text:sub(#digits+1),dx=#digits*advance,alpha=1} end
    return parts
end
return M

end)()
HUD.motion=(function()
-- Exact critically damped spring; all coordinates are 1080p reference pixels.
local M = {}
local function finite(x) return type(x)=='number' and x==x and math.abs(x)<1e8 end
function M.new() return {x=0,y=0,vx=0,vy=0,ready=false} end
function M.axis(x,v,target,dt,omega)
    local delta=x-target
    local j=v+omega*delta
    local e=math.exp(-omega*dt)
    return target+(delta+j*dt)*e,(v-omega*j*dt)*e
end
function M.step(s, target, dt, cfg)
    local x,y=0,0
    if target and finite(target.x) and finite(target.y) then
        x,y=target.x*cfg.follow,target.y*cfg.follow
    end
    local radius=math.sqrt(x*x+y*y)
    if radius>cfg.travel then x,y=x*cfg.travel/radius,y*cfg.travel/radius end
    if not finite(dt) or dt<0 then dt=0 end
    if not s.ready or dt>0.35 then s.x,s.y,s.vx,s.vy=x,y,0,0; s.ready=true end
    local omega=4.75/math.max(0.04,cfg.settle)
    s.x,s.vx=M.axis(s.x,s.vx,x,dt,omega)
    s.y,s.vy=M.axis(s.y,s.vy,y,dt,omega)
    -- Moving targets can retain momentum; enforce the hard travel envelope too.
    radius=math.sqrt(s.x*s.x+s.y*s.y)
    if radius>cfg.travel then
        s.x,s.y=s.x*cfg.travel/radius,s.y*cfg.travel/radius
        local outward=(s.vx*s.x+s.vy*s.y)/(cfg.travel*cfg.travel)
        if outward>0 then s.vx,s.vy=s.vx-outward*s.x,s.vy-outward*s.y end
    end
    return s.x,s.y
end
-- Limit lag relative to the moving weapon, never relative to screen center.
function M.attach(s,target,dt,cfg)
    if not finite(dt) or dt<0 then dt=0 end
    if not s.ready or dt>.35 then s.x,s.y,s.vx,s.vy=target.x,target.y,0,0;s.ready=true end
    local omega=4.75/cfg.weapon_settle
    s.x,s.vx=M.axis(s.x,s.vx,target.x,dt,omega)
    s.y,s.vy=M.axis(s.y,s.vy,target.y,dt,omega)
    local dx,dy=s.x-target.x,s.y-target.y;local d=math.sqrt(dx*dx+dy*dy)
    if d>cfg.weapon_lag then
        s.x,s.y=target.x+dx*cfg.weapon_lag/d,target.y+dy*cfg.weapon_lag/d
        s.vx,s.vy=0,0
    end
    return s.x,s.y
end
return M

end)()
