        if gui and main~=world then self.release() end
        local fold_commands
        if folded then folded.release();folded=nil end
        local m=p.matrix
        local x,y,z=HUD.scene_test.mount(p,c)
        local px=p.x+m[1]*x+m[5]*y+m[9]*z
        local py=p.y+m[2]*x+m[6]*y+m[10]*z
        local pz=p.z+m[3]*x+m[7]*y+m[11]*z
        if p.gui_pose then px,py,pz=p.x,p.y,p.z end
        if c.placement_mode=='auto' and p.first_person and not p.gui_pose then m=HUD.pose_motion.upright(m) end
        if c.keep_hud_upright and not p.gui_pose then m=HUD.pose_motion.upright(m) end
        m=HUD.pose_motion.step(smooth,m,px,py,pz,tostring(c.placement_mode)..':'..tostring(p.id)..':'..tostring(p.candidate),dt,c)
        px,py,pz=m[13],m[14],m[15]
        if first then log('WORLD_GUI matrix begin') end
        local pose=sr.Matrix4x4.from_axes(sr.Vector3(m[1],m[2],m[3]),
            sr.Vector3(m[5],m[6],m[7]),sr.Vector3(m[9],m[10],m[11]),sr.Vector3(px,py,pz))
        if not gui then
            world=main;log('WORLD_GUI create begin')
            gui=assert(W.create_world_gui(world,pose,1000,1000,'immediate'),'world GUI returned nil')
            log('WORLD_GUI create complete')
            local name='mods/dbf_hud/materials/depth_fill'
            local control='mods/dbf_hud/materials/depth_state_test_loader_control'
            if not direct and A.can_get and A.can_get('material',control) then depth_fill=control
            elseif not direct and A.can_get and A.can_get('material',name) then depth_fill=name
            elseif not direct and A.can_get and A.can_get('material','mods/astra_ammo/materials/depth_fill') then
                depth_fill='mods/astra_ammo/materials/depth_fill' -- Previously deployed optional material.
            end
            log('WORLD_GUI depth material '..(direct and 'not requested' or (depth_fill and 'available' or 'missing; install depth material addon')))
            -- One-time observation only: resolve the same material used by bitmap.
            -- Keep no native material handles across frames or GUI destruction.
            if c.debug_logging then
            log('WORLD_GUI instance '..identity(gui)..' world '..identity(world))
            if type(G.material)=='function' and A.can_get then
                for _,material_name in ipairs({'content/ui/shared/material/gui_fill',
                    depth_fill or 'mods/dbf_hud/materials/depth_fill','mods/dbf_hud/materials/depth_blur'}) do
                    if A.can_get('material',material_name) then
                        local ok,handle=pcall(G.material,gui,material_name)
                        log('WORLD_GUI material instance '..material_name..' '..(ok and identity(handle) or 'lookup failed'))
                    end
                end
            else log('WORLD_GUI material inspection unavailable') end
            end
        else
            if first then log('WORLD_GUI move begin') end
            G.move(gui,pose)
        end
        if commands then
            -- Native screen frost renders white on the verified world-GUI path.
            -- Keep the user's frost preference for screen modes; omit it here.
            -- Bitmap takes the material as a required argument. This avoids relying
            -- on the game's optional rect material overload matching upstream.
            local function solid(x,y,w,h,layer,color)
                if depth_fill then
                    G.bitmap(gui,depth_fill,sr.Vector3(x,y,layer),sr.Vector2(w,h),color)
                else G.rect(gui,sr.Vector3(x,y,layer),sr.Vector2(w,h),color) end
            end
            for _,v in ipairs(commands) do
                local color=sr.Color(math.floor(v.a*255+.5),v.c[1],v.c[2],v.c[3])
                if v.type=='panel' then
                    -- Match the known-working hybrid background; leave experimental
                    -- depth fill on foreground primitives only during this comparison.
                    solid(v.x,v.y,v.w,v.h,1,color)
                elseif v.type=='rect' then
                    solid(v.x,v.y,v.w,v.h,v.fuel_marker_piece and 3 or 2,color)
                else
                    local resource,material=HUD.native_font.resolve(sr,v.font,c.occlusion_mode~='gui')
                    if resource and not v.fuel_endpoint then
                        for _,part in ipairs(HUD.font.numeric_parts(v)) do
                            local part_color=sr.Color(math.floor(v.a*part.alpha*255+.5),v.c[1],v.c[2],v.c[3])
                            G.text(gui,part.text,resource,v.size,material,sr.Vector3(v.x+part.dx,v.y,3),part_color)
                        end
                    end

                end
            end
            if fold_commands and #fold_commands>0 then
                folded=folded or M.new(sr,log,direct)
                local child_panel=fold_commands[1];local edge=child_panel.y+child_panel.h
                local child={}
                for _,v in ipairs(fold_commands) do
                    local copy={};for k,value in pairs(v) do copy[k]=value end
                    copy.y=v.y-edge
                    if copy.type=='text' then
                        local a,b,e,f=HUD.font.measure(copy.text,copy.size,copy.font,true)
                        copy.x=child_panel.x+child_panel.w/2-(a+e)/2
                        copy.y=-child_panel.h/2-(b+f)/2
                    end
                    child[#child+1]=copy
                end
                local hinge=commands[1].y-2
                local upright=HUD.pose_motion.forward_tilt(m,-math.pi/2)
                local child_pose={matrix=upright,x=px+m[9]*hinge/1000,y=py+m[10]*hinge/1000,z=pz+m[11]*hinge/1000,id=p.id,candidate='folded reserve',gui_pose=true}
                folded.draw(child_pose,c,child,dt)
            end
            if first then log('WORLD_GUI panel submitted: '..(depth_fill and 'explicit material bitmap path' or 'default rectangle path'));first=false end
            self.status='world panel; frost unavailable on this rendering path';return true
        end
        if first then log('WORLD_GUI rect begin') end
        G.rect(gui,sr.Vector3(0,0,0),sr.Vector2(240,140),sr.Color(255,45,52,55))
        G.rect(gui,sr.Vector3(0,0,1),sr.Vector2(12,140),sr.Color(255,231,200,92))
        if first then log('WORLD_GUI rect complete');first=false end
        self.status='world rectangle submitted'
    end
    function self.draw(p,c,commands,dt)
        if failed then return end
        local ok,err=pcall(draw,p,c,commands,dt)
        if not ok then
            failed=true;self.status=tostring(err);log('WORLD_GUI Lua failure: '..self.status)
            pcall(self.release)
        end
        return ok and err==true
    end
    return self
end
return M


end)()
HUD.depth_marker=(function()
-- Isolated per-primitive depth marker. No Gui.move, profile edits or shared material writes.
local M={}
function M.new(sr,log)
    local gui,world,failed,access_reported,compare_reported;local ids={};local self={status='not started'}
    local material='mods/dbf_hud/materials/depth_state_test_loader_control'
    local access_material='mods/dbf_hud/materials/screen_scene_depth_access'
    local compare_material='mods/dbf_hud/materials/screen_scene_depth_compare'
    local function live(w)
        for _,v in pairs(sr.Application.worlds() or {}) do if v==w then return true end end
        return false
    end
    function self.release()
        if gui and live(world) then sr.World.destroy_gui(world,gui) end
        gui,world=nil,nil;ids={}
    end
    function self.draw(position,camera,fov,height,width)
        if failed then return false end
        if not position or not camera then self.release();return false end
        local ok,err=pcall(function()
            assert(type(sr.Gui.bitmap_3d)=='function','bitmap_3d unavailable')
            assert(sr.Application.can_get('material',material),'depth marker material unavailable')
            local main=sr.Application.main_world()
            local target=main
            if width then
                for _,candidate in pairs(sr.Application.worlds() or {}) do
                    if candidate~=main then target=candidate;break end
                end
            end
            if world~=target or not live(world) then self.release() end
            assert(live(target),'no GUI world')
            if not gui then
                world=target
                if width then gui=assert(sr.World.create_screen_gui(world,'scale',1,1))
                else gui=assert(sr.World.create_world_gui(world,sr.Matrix4x4.identity(),1,1,'immediate')) end
            end
            if width then
                for _,id in ipairs(ids) do sr.Gui.destroy_bitmap(gui,id) end
                ids={}
                local point=HUD.projection.project(camera,position.x,position.y,position.z,fov,width/height,.05)
                if not point then return end
                local radius,stroke=14*height/1080,1.5*height/1080
                local comparing=sr.Application.can_get('material',compare_material)
                local encoded=math.floor(math.max(0,math.min(64,point.depth))*65535/64+.5)
                local color=comparing and sr.Color(255,encoded%256,math.floor(encoded/256),0) or sr.Color(255,0,255,0)
                for _,edge in ipairs({{-radius,-radius,2*radius,stroke},{-radius,radius-stroke,2*radius,stroke},
                    {-radius,-radius,stroke,2*radius},{radius-stroke,-radius,stroke,2*radius}}) do
                    local id=sr.Gui.bitmap(gui,comparing and compare_material or material,sr.Vector3(point.x*width+edge[1],point.y*height+edge[2],50),
                        sr.Vector2(edge[3],edge[4]),color)
                    if id then ids[#ids+1]=id end
                end
                if comparing and not compare_reported then
                    compare_reported=true;log('SCENE_DEPTH comparison material loaded; green outline submitted; depth units provisional')
                end
                if not comparing and sr.Application.can_get('material',access_material) then
                    local side=128*height/1080
                    local id=sr.Gui.bitmap(gui,access_material,sr.Vector3(point.x*width+24*height/1080,
                        point.y*height-side*.5,50),sr.Vector2(side,side),sr.Color(255,255,255,255))
                    if id then ids[#ids+1]=id end
                    if not access_reported then
                        access_reported=true;log('SCENE_DEPTH access material loaded; screen tile submitted; texture contents unverified')
                    end
                end
                self.status='screen depth material submitted';return
            end
            local v=sr.Vector3
            local tm=sr.Matrix4x4.from_axes(v(camera[1],camera[2],camera[3]),
                v(camera[5],camera[6],camera[7]),v(camera[9],camera[10],camera[11]),
                v(position.x,position.y,position.z))
            local depth=(position.x-camera[13])*camera[5]+(position.y-camera[14])*camera[6]+(position.z-camera[15])*camera[7]
            if depth<=0 then return end
            local unit=2*depth*math.tan(fov*.5)/height
            local radius,stroke=10*height/1080*unit,1.5*height/1080*unit
            local color=sr.Color(255,255,0,255)
            for _,edge in ipairs({{-radius,-radius,2*radius,stroke},{-radius,radius-stroke,2*radius,stroke},
                {-radius,-radius,stroke,2*radius},{radius-stroke,-radius,stroke,2*radius}}) do
                sr.Gui.bitmap_3d(gui,material,tm,v(edge[1],edge[2],0),2,sr.Vector2(edge[3],edge[4]),color)
            end
            self.status='depth marker submitted'
        end)
        if not ok then failed=true;self.status=tostring(err);log('DEPTH_MARKER failure '..self.status);pcall(self.release) end
        return ok and (self.status=='depth marker submitted' or self.status=='screen depth material submitted')
    end
    return self
end
return M

end)()
HUD.offscreen_test=(function()
-- Isolated one-frame render test. Never renders from the update callback.
local M={}
function M.start(sr,log,globals,panel_provider,show_preview)
    globals=globals or _G
    local self={};local active=true;local submitted=false;local first_render=true
    local A,W,R,V,U,G=sr.Application,sr.World,sr.Renderer,sr.Viewport,sr.Unit,sr.Gui
    local world,viewport,target,camera,environment,gui
    local preview,preview_world
    local world_ready=false
    local source_ids={};local elapsed=0
    local texture_w,texture_h=64,64
    local density=panel_provider and 4 or 1
    function self.tick(dt,refresh_hz,scanline_strength)
        elapsed=elapsed+(dt or 0)
        if panel_provider and active and world and gui and (not world_ready or refresh_hz==0 or elapsed>=1/(refresh_hz or 60)) then
            elapsed=0
            local commands=panel_provider()
            if commands then
                local f=commands[1]
                assert(f.w>0 and f.h>0,'invalid panel bounds')
                if math.ceil(f.w*density)~=texture_w or math.ceil(f.h*density)~=texture_h then
                    self.resize_required=true;return
                end
                self.aspect=texture_w/texture_h
                local sx,sy=density,density
                for _,id in ipairs(source_ids) do G.destroy_rect(gui,id) end
                source_ids={}
                local function rect(x,y,w,h,c,a)
                    -- Preserve the selected RGB values; no experimental color transform.
                    local rgb=c
                    local function strip(bottom,height,factor)
                        local id=G.rect(gui,sr.Vector3((x-f.x)*sx,(bottom-f.y)*sy,1),sr.Vector2(w*sx,height*sy),sr.Color(math.floor(255*(a or 1)),math.floor(rgb[1]*factor+0.5),math.floor(rgb[2]*factor+0.5),math.floor(rgb[3]*factor+0.5)))
                        source_ids[#source_ids+1]=id
                    end
                    local strength=scanline_strength or 0
                    if strength<=0 then strip(y,h,1);return end
                    -- One dim row per four source pixels, aligned across all primitives.
                    -- Modulate RGB only: never paint opaque bands into clear texels.
                    local bottom=y
                    while bottom<y+h do
                        local row=math.floor(bottom-f.y+0.000001)
                        local top=math.min(y+h,f.y+row+1)
                        if top<=bottom then break end
                        strip(bottom,top-bottom,row%4==0 and (1-strength) or 1)
                        bottom=top
                    end
                end
                for _,c in ipairs(commands) do
                    if c.type=='text' then
                        -- Archived mesh glyph rendering removed.
                    else rect(c.x,c.y,c.w,c.h,c.c,c.a) end
                end
                world_ready=false;submitted=false
            end
        end
        if active and world and not world_ready then
            world_ready=true
            if type(W.update)=='function' then
                if not panel_provider then log('OFFSCREEN private world update begin') end
                local ok,err=pcall(W.update,world,0)
                if not panel_provider or not ok then log(ok and 'OFFSCREEN private world update complete' or ('OFFSCREEN private world update failed '..tostring(err))) end
                if not ok then active=false end
            else log('OFFSCREEN private world update unavailable') end
        end
    end
    local bridge=rawget(globals,'HUDRenderBridge');local unsubscribe
    function self.release()
        active=false
        if unsubscribe then unsubscribe();unsubscribe=nil end
        local ok=true
        local function destroy(fn,...)
            if not ok then return end
            local done,err=pcall(fn,...);ok=done
            if not done then log('OFFSCREEN cleanup failed '..tostring(err)) end
        end
        if preview then
            local live=false
            for _,w in pairs(A.worlds() or {}) do if w==preview_world then live=true end end
            if live then destroy(W.destroy_gui,preview_world,preview) end
            if ok then preview=nil end
        end
        if gui then destroy(W.destroy_gui,world,gui);if ok then gui=nil end end
        if viewport then destroy(A.destroy_viewport,world,viewport);if ok then viewport=nil end end
        if environment then destroy(W.destroy_shading_environment,world,environment);if ok then environment=nil end end
        if world then destroy(A.release_world,world);if ok then world=nil end end
        if target then destroy(R.destroy_resource,target);if ok then target=nil end end
        if ok then log('OFFSCREEN cleanup complete') end
    end
    if not bridge or bridge.api~=1 or type(bridge.subscribe)~='function' then
        local loader=rawget(globals,'CowboyBingusModLoader')
        local state=loader and loader.modules and loader.modules['mods/holographic_utility_display/render_bridge']
        log('OFFSCREEN blocked: startup HUD render bridge required; loader='..tostring(state)..'; render='..type(rawget(globals,'render')))
        self.waiting_for_bridge=true
        return self
    end
    if panel_provider then
        local commands=panel_provider()
        if not commands then self.waiting_for_panel=true;return self end
        texture_w,texture_h=math.ceil(commands[1].w*density),math.ceil(commands[1].h*density)
        assert(texture_w>0 and texture_h>0 and texture_w<=2048 and texture_h<=2048,'panel texture bounds invalid')
        self.aspect=texture_w/texture_h
    end
    local ok,err=pcall(function()
        for _,pair in ipairs({{A,'new_world'},{A,'release_world'},{A,'create_viewport'},{A,'destroy_viewport'},
            {A,'render_world'},{A,'can_get'},{W,'spawn_unit'},{W,'create_screen_gui'},
            {W,'destroy_gui'},{W,'destroy_shading_environment'},
            {U,'camera'},{R,'create_resource'},{R,'destroy_resource'},{V,'set_output_render_target'},
            {G,'rect'}}) do assert(pair[1] and type(pair[1][pair[2]])=='function','missing '..pair[2]) end
        local name='core/units/camera'
        if not A.can_get('unit',name) then name='core/appkit/units/camera/camera' end
        if not A.can_get('unit',name) then
            for _,ns_name in ipairs({'Camera','World','Application'}) do
                local names={};local ns=sr[ns_name]
                if type(ns)=='table' then for key,value in pairs(ns) do
                    if type(key)=='string' and type(value)=='function' and
                        (ns_name=='Camera' or key:lower():find('camera',1,true)) then names[#names+1]=key end
                end end
                table.sort(names);log('OFFSCREEN CAMERA_API '..ns_name..' '..table.concat(names,' '))
            end
            for _,candidate in ipairs({'core/appkit/units/camera','content/markers/camera_marker',
                'core/editor_slave/stingray_editor/editor_camera'}) do
                log('OFFSCREEN CAMERA_RESOURCE '..candidate..' '..tostring(A.can_get('unit',candidate)))
            end
        end
        assert(A.can_get('unit',name),'camera resource unavailable: '..name)
        local environment_name='core/stingray_renderer/environments/midday/midday'
        local default_environment=type(W.create_default_shading_environment)=='function'
        if not default_environment then
            assert(type(W.create_shading_environment)=='function','missing create_shading_environment')
            assert(A.can_get('shading_environment',environment_name),'default environment resource unavailable')
        end
        log('OFFSCREEN setup begin')
        world=assert(A.new_world())
        local unit=assert(W.spawn_unit(world,name))
        camera=assert(U.camera(unit,1),'camera unavailable')
        environment=assert(default_environment and W.create_default_shading_environment(world)
            or W.create_shading_environment(world,environment_name))
        viewport=assert(A.create_viewport(world,'offscreen_ui_weapon_screen'))
        target=assert(R.create_resource('render_target','R8G8B8A8',texture_w,texture_h))
        V.set_output_render_target(viewport,target)
        self.texture=target
        gui=assert(W.create_screen_gui(world,'scale',1,1))
        if not panel_provider then
        for i,color in ipairs({{230,60,60},{60,210,100},{60,110,230},{230,200,60}}) do
            G.rect(gui,sr.Vector3(((i-1)%2)*32,math.floor((i-1)/2)*32,1),sr.Vector2(32,32),
                sr.Color(255,color[1],color[2],color[3]))
        end
        end
        log(string.format('OFFSCREEN source GUI ready at %dx%d',texture_w,texture_h))
    end)
    if not ok then log('OFFSCREEN setup stopped '..tostring(err));self.release();return self end
    unsubscribe=bridge.subscribe('dbf_hud.offscreen',function(...)
        if active and world_ready and not submitted then
            submitted=true
            if first_render then log('OFFSCREEN render callback entered') end
            local done,why=pcall(A.render_world,world,camera,viewport,environment)
            if first_render or not done then log(done and 'OFFSCREEN render submitted; pixels unverified' or ('OFFSCREEN render failed '..tostring(why))) end
            first_render=false
            if done and show_preview~=false and not preview then
                local shown,reason=pcall(function()
                    log('OFFSCREEN preview preflight begin')
                    assert(type(G.material)=='function','Gui.material unavailable')
                    assert(sr.Material and type(sr.Material.set_resource)=='function','Material.set_resource unavailable')
                    assert(type(G.bitmap)=='function','Gui.bitmap unavailable')
                    assert(type(A.main_world)=='function','Application.main_world unavailable')
                    assert(A.can_get('material','content/ui/shared/material/gui_diffuse_map'),'preview material unavailable')
                    local main=assert(A.main_world())
                    preview_world=main
                    for _,candidate in pairs(A.worlds() or {}) do
                        if candidate~=main and candidate~=world then preview_world=candidate;break end
                    end
                    log('OFFSCREEN preview world '..(preview_world==main and 'main fallback' or 'HUD world'))
                    log('OFFSCREEN preview GUI create begin')
                    preview=assert(W.create_screen_gui(preview_world,'scale',1,1))
                    -- Independent control: visible geometry does not depend on the render target.
                    G.rect(preview,sr.Vector3(896,296,79),sr.Vector2(panel_provider and texture_w/density+8 or 200,panel_provider and texture_h/density+8 or 200),sr.Color(255,255,0,255))
                    G.rect(preview,sr.Vector3(panel_provider and 916+texture_w/density or 1104,300,80),sr.Vector2(48,48),sr.Color(255,255,255,255))
                    for i,color in ipairs({{255,0,0},{255,255,0},{0,255,0},{0,0,255},{128,128,128},{255,255,255}}) do
                        G.rect(preview,sr.Vector3(900+(i-1)*32,260,81),sr.Vector2(32,24),sr.Color(255,color[1],color[2],color[3]))
                    end
                    log('OFFSCREEN color comparison reference enabled')
                    log('OFFSCREEN preview material lookup begin')
                    for _,candidate in ipairs({'core/performance_hud/gui','content/ui/shared/material/gui_diffuse_map','content/ui/shared/material/gui_fill','content/ui/shared/material/gui_white_alpha'}) do
                        if A.can_get('material',candidate) then
                            local valid,result=pcall(function()
                                local ffi=require('ffi')
                                return string.format('0x%X',tonumber(ffi.cast('uintptr_t',G.material(preview,candidate))))
                            end)
                            log('OFFSCREEN material candidate '..candidate..' '..(valid and result or 'lookup failed'))
                        else log('OFFSCREEN material candidate '..candidate..' unavailable') end
                    end
                    local material=assert(G.material(preview,'content/ui/shared/material/gui_diffuse_map'))
                    log('OFFSCREEN material Lua type='..type(material)..'; target Lua type='..type(target))
                    local pointer_ok,pointers=pcall(function()
                        local ffi=require('ffi')
                        local mp=tonumber(ffi.cast('uintptr_t',material))
                        local tp=tonumber(ffi.cast('uintptr_t',target))
                        assert(mp and mp>=65536,'Gui.material returned a null or invalid native pointer')
                        assert(tp and tp>=65536,'render target returned a null or invalid native pointer')
                        return string.format('material=0x%X target=0x%X',mp,tp)
                    end)
                    assert(pointer_ok,pointers)
                    log('OFFSCREEN native pointer check '..pointers)
                    -- Native signature and diffuse_map slot verified; null handles rejected above.
                    log('OFFSCREEN verified texture binding begin')
                    sr.Material.set_resource(material,'diffuse_map',target)
                    log('OFFSCREEN preview bitmap draw begin')
                    G.bitmap(preview,'content/ui/shared/material/gui_diffuse_map',sr.Vector3(900,300,80),sr.Vector2(panel_provider and texture_w/density or 192,panel_provider and texture_h/density or 192),sr.Color(255,255,255,255))
                    log('OFFSCREEN four-color preview placed above/right of native bottom-left HUD')
                end)
                if not shown then log('OFFSCREEN preview stopped '..tostring(reason)) end
            end
        end
    end)
    log('OFFSCREEN waiting for render callback')
    return self
end
return M

end)()
HUD.world_style=(function()
-- Pure WorldGUI geometry scaling, frame fitting and visual presets.
local M={}
function M.prepare(commands,p,c)
                    local f=commands[1];local scale=240*(c.scale or 1)/f.w
                    if c.placement_mode=='auto' and p.first_person then scale=scale*.5 end;local centered={}
                    for _,command in ipairs(commands) do
                        local v={};for k,value in pairs(command) do v[k]=value end
                        v.x=(v.x-f.x-f.w/2)*scale;v.y=(v.y-f.y-f.h/2)*scale
                        if v.w then v.w=v.w*scale end
                        if v.h then v.h=v.h*scale end
                        if v.size then v.size=v.size*scale end
                        centered[#centered+1]=v
                    end
                    -- Pixel glyphs quantize after world scaling; fit their actual bounds.
                    if HUD.font.supported(c.font) then
                        local panel=centered[1]
                        local left,bottom,right,top=panel.x,panel.y,panel.x+panel.w,panel.y+panel.h
                        local padding=math.max(1,8*2*(c.scale or 1)*scale)
                        for _,v in ipairs(centered) do
                            if v.type=='text' and not v.child then
                                local a,b,e,f=HUD.font.measure(v.text,v.size,v.font,true)
                                left=math.min(left,v.x+a-padding);bottom=math.min(bottom,v.y+b-padding)
                                right=math.max(right,v.x+e+padding);top=math.max(top,v.y+f+padding)
                            end
                        end
                        for _,v in ipairs(centered) do
                            if v.decoration and not v.child then
                                v.x=left+(v.x-panel.x)*(right-left)/panel.w
                                v.y=bottom+(v.y-panel.y)*(top-bottom)/panel.h
                                v.w=v.w*(right-left)/panel.w
                                v.h=v.h*(top-bottom)/panel.h
                            end
                        end
                        panel.x,panel.y,panel.w,panel.h=left,bottom,right-left,top-bottom
                    end
                    -- World glyph scaling and frame fitting may change the final
                    -- bounds after screen-layout centering. Align actual glyphs here.
                    local panel=centered[1];local middle=panel.x+panel.w/2
                    local bar_left,bar_right=math.huge,-math.huge
                    for _,v in ipairs(centered) do
                        if v.heat_label then
                            local a,b,e,f=HUD.font.measure(v.text,v.size,v.font,true)
                            if not e then a,e=0,#v.text*v.size*.6 end
                            local pad=8*2*(c.scale or 1)*scale
                            if v.heat_label=='percent' then
                                local pa,pb,pe=HUD.font.measure(v.heat_prefix,v.size,v.font,true)
                                local slot_width=0
                                for digit=0,9 do local da,db,de=HUD.font.measure(tostring(digit),v.size,v.font,true);slot_width=math.max(slot_width,(de or v.size*.6)-(da or 0)) end
                                v.x=panel.x+pad+(pe or #v.heat_prefix*v.size*.6)+(v.heat_digit_slot or 0)*slot_width
                            else v.x=v.heat_label=='left' and panel.x+pad-a or panel.x+panel.w-pad-e end
                        elseif v.center_in_frame then
                            local a,b,e,f
                            if HUD.font.supported(v.font) then a,b,e,f=HUD.font.measure(v.text,v.size,v.font,true) end
                            if not e then a,e=0,#v.text*v.size*.6 end
                            v.x=middle-(a+e)/2
                        elseif v.center_bar then
                            bar_left=math.min(bar_left,v.x);bar_right=math.max(bar_right,v.x+v.w)
                        end
                    end
                    if bar_left<math.huge then
                        local shift=middle-(bar_left+bar_right)/2
                        for _,v in ipairs(centered) do if v.center_bar then v.x=v.x+shift end end
                    end
                    local heading;local icon_left,icon_right=math.huge,-math.huge
                    for _,v in ipairs(centered) do
                        if v.mode_count then heading=v end
                        if v.mode_icon then icon_left=math.min(icon_left,v.x);icon_right=math.max(icon_right,v.x+v.w) end
                    end
                    if heading and icon_left<math.huge then
                        local a,b,e,f
                        if HUD.font.supported(heading.font) then a,b,e,f=HUD.font.measure(heading.text,heading.size,heading.font,true) end
                        if not e then a,e=0,#heading.text*heading.size*.6 end
                        local gap=8*scale;local width=e-a+gap+icon_right-icon_left
                        local start=middle-width/2;heading.x=start-a
                        local shift=start+e-a+gap-icon_left
                        for _,v in ipairs(centered) do if v.mode_icon then v.x=v.x+shift end end
                    end
                    local fuel_left,fuel_right=math.huge,-math.huge
                    for _,v in ipairs(centered) do
                        if v.fuel_group then
                            local a,e=0,v.w or 0
                            if v.type=='text' then
                                local b,f
                                a,b,e,f=HUD.font.measure(v.text,v.size,v.font,true)
                                if not e then a,e=0,#v.text*v.size*.6 end
                            end
                            fuel_left=math.min(fuel_left,v.x+a);fuel_right=math.max(fuel_right,v.x+e)
                        end
                    end
                    if fuel_left<math.huge then
                        local shift=middle-(fuel_left+fuel_right)/2
                        for _,v in ipairs(centered) do if v.fuel_group then v.x=v.x+shift end end
                    end
                    local child_panel,child_text
                    for _,v in ipairs(centered) do
                        if v.child and not v.heat_child and v.type=='panel' then child_panel=v end
                        if v.child and not v.heat_child and v.type=='text' then child_text=v end
                    end
                    if child_panel and child_text then
                        local old={x=child_panel.x,y=child_panel.y,w=child_panel.w,h=child_panel.h}
                        local a,b,e,f
                        if HUD.font.supported(child_text.font) then a,b,e,f=HUD.font.measure(child_text.text,child_text.size,child_text.font,true) end
                        if not e then a,b,e,f=0,-child_text.size*.2,#child_text.text*child_text.size*.6,child_text.size*.8 end
                        local pad=4*2*(c.scale or 1)*scale
                        local width,height=panel.w,f-b+2*pad
                        child_panel.x=middle-width/2;child_panel.y=panel.y-2*2*(c.scale or 1)*scale-height
                        child_panel.w,child_panel.h=width,height
                        child_text.x=middle-(a+e)/2;child_text.y=child_panel.y+pad-b
                        for _,v in ipairs(centered) do
                            if v.child and not v.heat_child and v.decoration then
                                v.x=child_panel.x+(v.x-old.x)*width/old.w
                                v.y=child_panel.y+(v.y-old.y)*height/old.h
                                v.w=v.w*width/old.w;v.h=v.h*height/old.h
                            end
                        end
                    end
                    for _,v in ipairs(centered) do
                        if v.heat_overlay then
                            local inset=2*(c.scale or 1)*scale
                            v.x,v.y=panel.x+inset,panel.y+inset
                            v.w=math.max(0,panel.w-2*inset)*v.heat_fraction
                            v.h=math.max(0,panel.h-2*inset)
                        end
                    end
                    if c.style_3d=='hologram' then
                        local panel=centered[1];local clock=c.style_clock or 0
                        local flicker=.96+.025*math.sin(clock*17)+.015*math.sin(clock*31)
                        for _,v in ipairs(centered) do v.a=v.a*flicker end
                        panel.a=panel.a*.18
                        if child_panel then child_panel.a=child_panel.a*.18 end
                        local ink=HUD.config.rgb(c.text_color)
                        local strength=c.visibility_alpha or (commands[2] and commands[2].a) or 1
                        local frames={panel}
                        if child_panel then frames[#frames+1]=child_panel end
                        for _,frame in ipairs(frames) do
                            local thickness=math.max(.3,frame.w/500)
                            for _,edge in ipairs({{frame.x,frame.y,frame.w,thickness},{frame.x,frame.y+frame.h-thickness,frame.w,thickness}}) do
                                centered[#centered+1]={type='rect',x=edge[1],y=edge[2],w=edge[3],h=edge[4],c=ink,a=.18*strength}
                            end
                            centered[#centered+1]={type='rect',x=frame.x,y=frame.y+(clock*.35%1)*(frame.h-thickness),w=frame.w,h=thickness,c=ink,a=.10*strength}
                        end
                    end
    if c.style_3d=='instrument' or c.style_3d=='blueprint' or c.style_3d=='retro' then
        local blueprint,retro=c.style_3d=='blueprint',c.style_3d=='retro'
        local accent=retro and HUD.config.rgb(c.text_color) or blueprint and {92,194,230} or {235,175,70}
        local frames={};for _,v in ipairs(centered) do if v.type=='panel' then frames[#frames+1]=v end end
        for _,frame in ipairs(frames) do
            if not retro and c.background_color=='#202628' then frame.c=blueprint and {12,28,42} or {35,28,17} end
            local t=math.max(.45,frame.w/180)
            local function line(x,y,w,h,alpha)
                centered[#centered+1]={type='rect',x=x,y=y,w=w,h=h,c=accent,a=alpha*(c.visibility_alpha or 1)}
            end
            if retro then
                for k=1,21 do line(frame.x,frame.y+frame.h*k/22,frame.w,t*.5,.14) end
            elseif blueprint then
                for k=1,7 do line(frame.x+frame.w*k/8,frame.y,t*.4,frame.h,.09) end
                for k=1,3 do line(frame.x,frame.y+frame.h*k/4,frame.w,t*.4,.09) end
            end
        end
    end
    HUD.layout.fuel_marker(centered,function(t,size,font)return HUD.font.measure(t,size,font,true)end)
    return centered
end
return M

end)()
HUD.archived_mesh=(function()
-- Archived mesh carrier. Production uses direct WorldGUI.
local M={}
function M.new(sr,log,side)
    local A,W,U,Mesh=sr.Application,sr.World,sr.Unit,sr.Mesh
    local unit,world,bound,scene_material,last_emission,screen_test;local failed=false;local smooth={}
    local self={}
    local function live(w)
        for _,v in pairs(A.worlds() or {}) do if w==v then return true end end
        return false
    end
    function self.release()
        if unit and live(world) then W.destroy_unit(world,unit) end
        unit,world,bound,scene_material,last_emission=nil,nil,nil,nil,nil;smooth={}
    end
    function self.draw(p,c,target,dt,aspect)
        if failed then return end
        if not p or not target then if unit then self.release() end;return end
        local ok,err=pcall(function()
            local main=A.main_world()
            if not live(main) then return end
            if unit and (world~=main or not live(world)) then self.release() end
            if unit and screen_test~=(c.weapon_screen_test==true) then self.release() end
            if not unit then
                local name='content/art_shared/meshes/plane_primitive'
                assert(A.can_get('unit',name),'plane unit unavailable')
                for _,fn in ipairs({'set_local_pose','set_local_scale','num_meshes','mesh'}) do assert(type(U[fn])=='function','missing Unit.'..fn) end
                assert(Mesh and type(Mesh.num_materials)=='function' and type(Mesh.material)=='function','mesh material API unavailable')
                world=main
                for _,candidate in ipairs({'mods/dbf_hud/materials/fullbright_depth_image','core/appkit/materials/loading_screen','content/effects/base_shaders/mesh_particle_simple','content/env_ship/hangar/props/materials/store_screen_large','content/fac_helldivers/equipment/primary_weapons/assault_rifle_nacho/materials/weapon_screen'}) do
                    log('SCENE fullbright candidate '..candidate..' loaded='..tostring(A.can_get('material',candidate)))
                end
                log('SCENE plane spawn begin')
                unit=assert(W.spawn_unit(world,name))
                assert(U.num_meshes(unit)==1,'unexpected mesh count')
                if type(U.set_mesh_visibility)=='function' then
                    log('SCENE shadow-only visibility begin side='..side)
                    U.set_mesh_visibility(unit,1,false,'shadow_caster')
                    log('SCENE shadow-only visibility returned side='..side)
                end
                local mesh=U.mesh(unit,1)
                assert(Mesh.num_materials(mesh)==1,'unexpected material count')
                local transparent='content/art_shared/materials/placeholder_red_transparent'
                screen_test=c.weapon_screen_test==true
                if screen_test then transparent='content/fac_helldivers/equipment/primary_weapons/assault_rifle_nacho/materials/weapon_screen' end
                local alpha=type(U.set_material)=='function' and A.can_get('material',transparent)
                if screen_test then assert(alpha,'weapon screen material unavailable') end
                if alpha then
                    -- Unit asset declares the named slot 'material' (thin hash eac0b497).
                    log('SCENE transparent material assignment begin')
                    U.set_material(unit,'material',transparent)
                end
                local material=Mesh.material(mesh,1)
                local ffi=require('ffi')
                assert(tonumber(ffi.cast('uintptr_t',material))>=65536,'invalid scene material')
                assert(tonumber(ffi.cast('uintptr_t',target))>=65536,'invalid panel texture')
                log('SCENE verified material texture bind begin')
                if screen_test then
                    sr.Material.set_resource(material,'input_image',target)
                    sr.Material.set_scalar(material,'screen_enabled',1)
                    sr.Material.set_vector4(material,'screen_rect',sr.Vector4(side==-1 and 1 or 0,0,side==-1 and -1 or 1,1))
                    sr.Material.set_vector2(material,'Atlas_size',sr.Vector2(1,1))
                    sr.Material.set_vector2(material,'resolution_multiplier',sr.Vector2(1,1))
                    for _,name in ipairs({'normal_map_amount','normal_map_coloring_amount','dirt_amount','distortion_amount','artifacts_amount','light_bleed_amount','use_dropshadow'}) do
                        sr.Material.set_scalar(material,name,0)
                    end
                    log('SCENE weapon screen image bound side='..side..'; appearance unverified')
                else
                sr.Material.set_resource(material,'color_map',target)
                sr.Material.set_resource(material,'emissive_map',target)
                sr.Material.set_scalar(material,'use_color_map',1)
                sr.Material.set_scalar(material,'use_emissive_map',1)
                if side==-1 then
                    sr.Material.set_vector2(material,'uv_scale',sr.Vector2(-1,1))
                    sr.Material.set_vector2(material,'uv_offset',sr.Vector2(1,0))
                end
                scene_material=material
                sr.Material.set_vector3(material,'base_color',sr.Vector3(0,0,0))
                -- Diagnostic: black metallic base removes the dielectric reflection term.
                sr.Material.set_scalar(material,'use_metallic_map',0)
                sr.Material.set_scalar(material,'metallic',1)
                sr.Material.set_scalar(material,'use_roughness_map',0)
                sr.Material.set_scalar(material,'roughness',1)
                sr.Material.set_vector3(material,'emissive',sr.Vector3(1,1,1))
                if alpha then
                    sr.Material.set_scalar(material,'opacity',1)
                    sr.Material.set_scalar(material,'use_opacity_map',1)
                    log('SCENE transparent material bound; alpha pixels unverified')
                end
                end
                scene_material=material
                bound=target
                log('SCENE plane texture bound')
            end
            assert(bound==target,'render target changed without scene retirement')
            if last_emission~=c.emissive_intensity then
                sr.Material.set_scalar(scene_material,screen_test and 'emissive_amount' or 'emissive_intensity',c.emissive_intensity)
                last_emission=c.emissive_intensity
            end
            local m=p.matrix
            local x,y,z=HUD.scene_test.mount(p,c)
            local px=p.x+m[1]*x+m[5]*y+m[9]*z
            local py=p.y+m[2]*x+m[6]*y+m[10]*z
            local pz=p.z+m[3]*x+m[7]*y+m[11]*z
            m=HUD.pose_motion.step(smooth,m,px,py,pz,tostring(p.id)..':'..tostring(p.candidate),dt,c)
            local pose=sr.Matrix4x4.from_axes(sr.Vector3(side*m[1],side*m[2],side*m[3]),sr.Vector3(m[9],m[10],m[11]),sr.Vector3(-side*m[5],-side*m[6],-side*m[7]),sr.Vector3(m[13],m[14],m[15]))
            U.set_local_pose(unit,1,pose)
            U.set_local_scale(unit,1,sr.Vector3(0.24,0.24/math.max(0.25,math.min(8,aspect or 2)),0.24))
        end)
        if not ok then failed=true;log('SCENE stopped '..tostring(err));self.release() end
    end
    return self
end
function M.fullbright(sr,log)
    local gui,world,bound;local stopped=false;local smooth={}
    local A,W,G=sr.Application,sr.World,sr.Gui
    local self={}
    function self.release()
        if gui then
            for _,w in pairs(A.worlds() or {}) do if w==world then W.destroy_gui(world,gui);break end end
        end
        gui,world,bound=nil,nil,nil;smooth={}
    end
    function self.draw(p,c,target,dt,aspect)
        if stopped or not G or not W.create_world_gui then return end
        if not p or not target then self.release();return end
        local ok,err=pcall(function()
            local main=A.main_world()
            if gui and world~=main then self.release() end
            local name='mods/dbf_hud/materials/fullbright_depth_image'
            if not A.can_get('material',name) then return end
            local x,y,z=HUD.scene_test.mount(p,c)
            local m=p.matrix
            local px=p.x+m[1]*x+m[5]*y+m[9]*z
            local py=p.y+m[2]*x+m[6]*y+m[10]*z
            local pz=p.z+m[3]*x+m[7]*y+m[11]*z
            m=HUD.pose_motion.step(smooth,m,px,py,pz,tostring(p.id)..':'..tostring(p.candidate),dt,c)
            local pose=sr.Matrix4x4.from_axes(sr.Vector3(m[1],m[2],m[3]),sr.Vector3(m[5],m[6],m[7]),sr.Vector3(m[9],m[10],m[11]),sr.Vector3(m[13],m[14],m[15]))
            if not gui then
                world=main
                log('FULLBRIGHT main-world GUI create begin')
                gui=assert(W.create_world_gui(world,pose,1000,1000,'immediate'))
                local material=G.material(gui,name)
                local ffi=require('ffi')
                assert(tonumber(ffi.cast('uintptr_t',material))>=65536,'null fullbright material')
                assert(tonumber(ffi.cast('uintptr_t',target))>=65536,'null fullbright target')
                sr.Material.set_resource(material,'diffuse_map',target)
                bound=target
                log('FULLBRIGHT image material bound')
            else G.move(gui,pose) end
            assert(bound==target,'fullbright target changed without cleanup')
            G.bitmap(gui,name,sr.Vector3(-120,-120/(aspect or 2),0),sr.Vector2(240,240/(aspect or 2)),sr.Color(255,255,255,255))
        end)
        if not ok then stopped=true;log('FULLBRIGHT stopped '..tostring(err));pcall(self.release) end
    end
    return self
end
return M

end)()
HUD.scene_test=(function()
-- WorldGUI display selection; archived mesh access remains for research.
local M={}
function M.mount(p,c)
    local x,y,z
    if c.placement_mode=='auto' and p.auto_mount then x,y,z=p.auto_mount.x,p.auto_mount.y,p.auto_mount.z
    elseif p.first_person then x,y,z=c.fp_mount_x,c.fp_mount_y,c.fp_mount_z+.2
    elseif p.left_shoulder then x,y,z=c.left_mount_x,c.left_mount_y,c.left_mount_z+.2
    else x,y,z=c.mount_x,c.mount_y,c.mount_z+.2 end
    return x,y+.0762,z -- Shared three-inch forward shift; Purifier tuned forward and right corrections are external.
end
function M.new(sr,log,side)
    if not side then
        local front,back=M.new(sr,log,1),M.new(sr,log,-1)
        local overlay=HUD.world_probe.new(sr,log,true)
        local depth_overlay=HUD.world_probe.new(sr,log,false)
        local active_mode
        return {
            draw=function(p,c,target,dt,aspect,commands)
                local mode=c.occlusion_mode or (c.hud_occlusion~=false and 'gui_depth' or 'gui')
                if mode=='mesh' then mode='gui_depth' end -- archived selection
                if active_mode~=mode then
                    front.release();back.release();overlay.release();depth_overlay.release()
                    active_mode=mode
                    log('HUD occlusion mode '..mode)
                end
                do
                    if not commands then overlay.release();depth_overlay.release();return end
                    local centered=HUD.world_style.prepare(commands,p,c)
                    if mode=='gui_depth' then return depth_overlay.draw(p,c,centered,dt) else return overlay.draw(p,c,centered,dt) end
                end
            end,
            release=function() overlay.release();depth_overlay.release();front.release();back.release();active_mode=nil end
        }
    end
    return HUD.archived_mesh.new(sr,log,side)
end
function M.fullbright(sr,log)return HUD.archived_mesh.fullbright(sr,log)end
return M

end)()
HUD.screen_scene=(function()
-- Project saved world layouts into the UI world; compare scene depth in shaders.
-- Native atlas glyphs become textured quads, not replacement bitmap lettering.
local M={}
function M.panel_pose(p,c,commands)
    local m=p.matrix;local x,y,z=HUD.scene_test.mount(p,c)
    local at={x=p.x+m[1]*x+m[5]*y+m[9]*z,
        y=p.y+m[2]*x+m[6]*y+m[10]*z,z=p.z+m[3]*x+m[7]*y+m[11]*z}
    if not c.debug_sight_root_orientation and p.attach_point~='root' and p.sight and p.sight.matrix then
        local anchor=p.sight
        local dx,dy,dz=x-anchor.x,y-anchor.y,z-anchor.z
        m=anchor.matrix
        at={x=m[13]+m[1]*dx+m[5]*dy+m[9]*dz,
            y=m[14]+m[2]*dx+m[6]*dy+m[10]*dz,
            z=m[15]+m[3]*dx+m[7]*dy+m[11]*dz}
    elseif c.placement_mode=='auto' and p.first_person then m=HUD.pose_motion.upright(m) end
    if c.keep_hud_upright then m=HUD.pose_motion.upright(m) end
    local angle=math.rad(c.panel_rotation or 0)
    if angle~=0 then
        local rotated={};for i=1,16 do rotated[i]=m[i] end
        local co,si=math.cos(angle),math.sin(angle)
        for i=1,3 do
            rotated[i]=m[i]*co+m[i+8]*si
            rotated[i+8]=m[i+8]*co-m[i]*si
        end
        m=rotated
    end
    for _,turn in ipairs({{c.panel_pitch or 0,5,9},{c.panel_yaw or 0,1,5}}) do
        if turn[1]~=0 then
            local rotated={};for i=1,16 do rotated[i]=m[i] end
            local co,si=math.cos(math.rad(turn[1])),math.sin(math.rad(turn[1]))
            for i=0,2 do
                local a,b=turn[2]+i,turn[3]+i
                rotated[a]=m[a]*co+m[b]*si;rotated[b]=m[b]*co-m[a]*si
            end
            m=rotated
        end
    end
    return m,at
end
function M.point(m,at,x,y)
