    ['bccf91e5']='root',
    ['c03596c1']='hammer',
    ['c0978950']='c_scope',
    ['ca03689c']='bolt',
    ['e7f88e90']='attach_mag',
}
function M.new(hud,backend,log)
    local e={active=false,view='right',status='Equip a weapon, then enable editing'}
